import React from 'react'
import { useState } from 'react';
import { ThemeToggle } from './ThemeToggle';
import usePageProgress from '../hooks/usePageProgress';
import { IoMenuOutline } from "react-icons/io5";

const expand = () => {
  console.log("EXPANDED!!!")
  const burger = document.getElementById("burger");
  
  if (burger.className === 'Nav-Links-Burger') {
    burger.className += ' expanded raised br16';
  }
  else { 
    burger.className = "Nav-Links-Burger";
  }
};

export const NavBar = () => {

  const links = [
    { ref: "#2", text: "About"},
    { ref: "#3", text: "Projects"},
    { ref: "https://drive.google.com/file/d/1B6leOz-cMjweCFew0U56NWlvMwF53mWn/view?usp=sharing", text: "Resume"}
  ];

  const completion = usePageProgress();

  const [active, setActive] = useState(null);
  const handleMouseDown = (index) => {
    setActive(index);
  };
  const handleMouseUp = () => {
    setActive(null);
  };

  return (
    <div className='nav-bar'>
      <div className='Content nav-height'>
        <div className='inline'>
          <div className='Corner-Title'><a href='#0'>Caden Conde</a></div>
          <div className='Nav-Links'>
            <ThemeToggle />
            {links.map((link, index) => (
              <a
                className={`br16 ${active === index ? "inset" : "raised"}`}
                onMouseDown={() => handleMouseDown(index)}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseUp}
                href={link.ref}
              >
                {link.text}
              </a>
            ))}
          </div>

          <div className='Nav-Links-Collapse'>
            <ThemeToggle />
            <IoMenuOutline onClick={() => expand()} size={50} />
            <div className='Nav-Links-Burger' id="burger">
              <a href="#2">About</a><br/>
              <a href="#3">Projects</a><br />
              <a href="https://drive.google.com/file/d/1B6leOz-cMjweCFew0U56NWlvMwF53mWn/view?usp=sharing">Resume</a>
            </div>
          </div>
        </div>
      </div>
      <span style={{transform: `translateX(${completion-100}%)`}} className='Scroll-Indicator' />
    </div>
  )
}
