import React from 'react';
import { useEffect } from 'react';
import { AiOutlineJava, AiOutlineJavaScript, AiOutlinePython } from "react-icons/ai";
import { IoLogoCss3 } from "react-icons/io";
import { TbSql, TbBrandReactNative  } from "react-icons/tb";
import { FaPhp, FaReact, FaHtml5, FaNodeJs } from "react-icons/fa";

const componentsContext = require.context('../imgs', false, /\.(png|jpe?g|svg|webp)$/);

export const ProjCard = (props) => {
    const imagePath = componentsContext(`./${props.src}`);
    const projLink = [];
    
    const icons = {
        JavaScript: AiOutlineJavaScript,
        CSS: IoLogoCss3,
        HTML: FaHtml5,
        Node: FaNodeJs,
        SQL: TbSql,
        ReactNative: TbBrandReactNative,
        PHP: FaPhp,
        Python: AiOutlinePython,
        Java: AiOutlineJava,
        React: FaReact,
    };


    projLink.push(<a href={props.gitLink} className='Proj-Link'><div className='Proj-Link-Box br16 raised'>View Project</div></a>)

    return (
        <div className='Proj-Card raised br16'>
            <img className='Proj-Thumbnail br16' src={imagePath} alt="Thumbnail of Project"/>
            <div className='Project-Card-Title'>{props.title}</div>
            <p className='Project-Card-Content'>{props.children}</p>
            <div className='Proj-Card-Footer'>
                {projLink}
                <div className='proj-languages'>
                    {props.languages.map((lang) => {
                        const IconComponent = icons[lang];
                        return IconComponent ? <div className='proj-icon-box'><IconComponent key={lang} size={32} /></div> : null;
                    })}
                </div>
            </div>
        </div>
    )
}
