import React, { useState } from "react";
import { AiOutlineMail, AiFillLinkedin } from "react-icons/ai";
import { DiGithubBadge } from "react-icons/di";

const Footer = () => {
  const size = 54;
  
  const links = [
    { href: "mailto:cadenconde@gmail.com", icon: <AiOutlineMail size={size} /> },
    { href: "https://github.com/CadenConde", icon: <DiGithubBadge size={size} /> },
    { href: "https://www.linkedin.com/in/caden-conde/", icon: <AiFillLinkedin size={size} /> }
  ];

  const [active, setActive] = useState(null);

  const handleMouseDown = (index) => {
    setActive(index);
  };

  const handleMouseUp = () => {
    setActive(null);
  };

  return (
    <footer className="footer">
      {/* <div className="Content"> */}
        <div className="footer-content">
          <span className="footer-left">CadenConde&copy;2025</span>
          <a href="#0" className="footer-center footer-link">Caden Conde</a>
          <div className="footer-right footer-icons">
            {links.map((link, index) => (
              <a
                key={index}
                href={link.href}
                className={`br16 ${active === index ? "inset" : "raised"}`}
                onMouseDown={() => handleMouseDown(index)}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseUp}
              >
                <span className="ico">{link.icon}</span>
              </a>
            ))}
          </div>
          {/* </div> */}
        </div>
    </footer>
  );
};

export default Footer;