import React from 'react'
import { useState } from 'react';
import { DiGithubBadge } from "react-icons/di";
import { AiFillLinkedin, AiOutlineMail } from "react-icons/ai";



  

export const Hero = () => {
  const size = 70;

  const links = [
    { href: "mailto:cadenconde@gmail.com", icon: <AiOutlineMail size={size} /> },
    { href: "https://github.com/CadenConde", icon: <DiGithubBadge size={size} /> },
    { href: "https://www.linkedin.com/in/caden-conde/", icon: <AiFillLinkedin size={size} /> }
  ];

  const [active, setActive] = useState(null);

  const handleMouseDown = (index) => {
    setActive(index);
  };

  const handleMouseUp = () => {
    setActive(null);
  };


  return (
    <div className='Hero-Container'>

      <svg width="0" height="0">
        <defs>
          <linearGradient id="icon-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="var(--primary2)" />
            <stop offset="100%" stopColor="var(--primary)" />
          </linearGradient>
        </defs>
      </svg>

      <div className='Content'>
        <span id="0" className='anchor'></span>
        <div className='Intro'>
          <div className='hero left'>
            Hello! I am
          </div>
          <div className='hero center'>
            <span className='name-emphasis'>Caden Conde</span>
          </div>
          <div className='hero right'>
            Computer Science Student
          </div>
          <div className='hero-icons center'>
            {links.map((link, index) => (
              <a
                key={index}
                href={link.href}
                className={`br16 ${active === index ? "inset" : "raised"}`}
                onMouseDown={() => handleMouseDown(index)}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseUp} // Ensures the effect resets if the user drags away
              >
                <span className="ico">{link.icon}</span>
              </a>
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}
